<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { listPayments, refundPayment, type Payment } from "../api"; const payments = ref<Payment[]>([]); const error = ref(""); const status = ref(""); const filtered = computed(() => payments.value.filter((payment) => !status.value || payment.status === status.value)); const money = (value: number) => new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR" }).format(value / 100); async function load() { try { payments.value = await listPayments(); } catch (reason) { error.value = (reason as Error).message; } } async function refund(id: string) { await refundPayment(id); await load(); } onMounted(load);</script><template><section><header><div><p class="eyebrow">TPV</p><h1>Cobros <span class="count">{{ filtered.length }}</span></h1></div><RouterLink class="button-link" :to="{ name: 'payments.create' }">Registrar cobro</RouterLink></header><div class="filter-bar"><select v-model="status"><option value="">Todos los estados</option><option value="paid">Cobrados</option><option value="refunded">Reembolsados</option></select><RouterLink :to="{ name: 'payments.cash-register' }">Caja diaria</RouterLink><RouterLink :to="{ name: 'payments.reports' }">Informes</RouterLink></div><p v-if="error" class="feedback error">{{ error }}</p><div class="customer-list"><p v-if="!filtered.length" class="empty">No hay cobros registrados.</p><div v-else v-for="payment in filtered" :key="payment.id" class="customer-row"><RouterLink :to="{ name: 'payments.detail', params: { id: payment.id } }"><strong>{{ money(payment.amountCents) }}</strong></RouterLink><span>{{ payment.method }}</span><span>{{ new Date(payment.createdAt).toLocaleDateString("es-ES") }}</span><button v-if="payment.status === 'paid'" class="secondary" @click="refund(payment.id)">Reembolsar</button><span v-else class="status-pill">Reembolsado</span></div></div></section></template>